sys_script_include.script:
var OutageShieldServiceResolver = Class.create();

OutageShieldServiceResolver.prototype = {

    initialize: function() {},

    getOfferingId: function(serviceKey) {

        // Only approved employee-facing choices.
        var offeringIds = {
            github: 'ac39faf647085b105a3ab4fe316d4361',
            website: '8e9507b447dcdb105a3ab4fe316d439a'
        };

        serviceKey = String(serviceKey || '');

        if (!Object.prototype.hasOwnProperty.call(
            offeringIds, serviceKey
        )) {
            return '';
        }

        var offeringId = offeringIds[serviceKey];

        if (!/^[0-9a-f]{32}$/i.test(offeringId)) {
            return '';
        }

        // Server-side validation against an approved record.
        var offering = new GlideRecord('service_offering');

        if (!offering.get(offeringId)) {
            return '';
        }

        return offering.getUniqueValue();
    },

    type: 'OutageShieldServiceResolver'
};
